import { createInertiaApp, router } from '@inertiajs/react';
import { Toaster } from '@/components/ui/sonner';
import { TooltipProvider } from '@/components/ui/tooltip';
import { initializeTheme } from '@/hooks/use-appearance';
import AppLayout from '@/layouts/app-layout';
import AuthLayout from '@/layouts/auth-layout';
import SettingsLayout from '@/layouts/settings/layout';
import SiteLayout from './layouts/site-layout';
// `ziggy.d.ts` is generated by `php artisan ziggy:generate --types` and only
// augments `ziggy-js`'s `RouteList`; it doesn't type the sibling `ziggy.js`
// module's actual runtime export, so the import below needs a type-check
// escape hatch rather than a (generator-overwritten) manual declaration.
// @ts-expect-error -- see comment above
import { Ziggy } from './ziggy';

declare global {
    // eslint-disable-next-line no-var -- required to augment the global scope `ziggy-js` reads from
    var Ziggy: Record<string, unknown> | undefined;
}

// `ziggy-js`'s bare `route()` helper (used throughout the app) resolves its
// route config from the global `Ziggy` variable that Laravel's `@routes`
// Blade directive injects into the page `<head>`. That script tag only
// exists in the final rendered HTML, so it's unavailable during Inertia's
// SSR pass on the Node server — without this, any component that calls
// `route()` during render (not just inside an event handler) crashes SSR
// with "Cannot read properties of undefined". Seed the global here so SSR
// has a working route config; the client keeps using the server-injected
// `Ziggy` (richer, request-specific) since this only fills the gap when it
// isn't already defined.
if (typeof window === 'undefined' && typeof globalThis.Ziggy === 'undefined') {
    globalThis.Ziggy = Ziggy;
}

function resolveAppName(): string {
    return (
        (router.page?.props?.name as string | undefined) ??
        import.meta.env.VITE_APP_NAME ??
        'New Egypt Group'
    );
}

createInertiaApp({
    title: (title) => {
        const appName = resolveAppName();
        return title ? `${title} - ${appName}` : appName;
    },
    layout: (name) => {
        switch (true) {
            case name === 'welcome':
                return null;
            case name.startsWith('auth/'):
                return AuthLayout;
            case name.startsWith('settings/'):
                return [AppLayout, SettingsLayout];
            case name.startsWith('admin'):
                return AppLayout;
            default:
                return SiteLayout;
        }
    },
    strictMode: true,
    withApp(app) {
        return (
            <TooltipProvider delayDuration={0}>
                {app}
                <Toaster />
            </TooltipProvider>
        );
    },
    progress: {
        color: '#4B5563',
    },
});

// This will set light / dark mode on load...
initializeTheme();
